def singleNumberIII(nums: list[int]) -> list[int]:
    xor_all = 0
    for x in nums: xor_all ^= x
    diff_bit = xor_all & (-xor_all)
    a = b = 0
    for x in nums:
        if x & diff_bit:
            a ^= x
        else:
            b ^= x
    return sorted([a, b])

